def _coerce(result):
    if result is None:
        return Decision.allow()
    if isinstance(result, Decision):
        return result
    raise TypeError("handle() must return a Decision or None, got %r" % (type(result),))


def _read_payload(stream):
    # Decode bytes ourselves rather than trust the platform locale -- a BOM'd or non-UTF-8
    # stdin must not silently disable the gate. See agentseam.dispatch for the incident
    # this guards: a Windows console's cp1252 layer turning a UTF-8 BOM into three bytes
    # json cannot parse, with the hook allowing everything while claiming enforcement.
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        return buffer.read().decode("utf-8-sig", errors="replace")
    return stream.read().lstrip("\ufeff")


def _emit(out, text):
    buffer = getattr(out, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        out.write(text)
        out.flush()


def _report(text):
    # Best effort, never raising: a diagnostic must not pre-empt the refusal it accompanies.
    # A hook's stderr is whatever the host gave it -- closed (then sys.stderr is None, and
    # the traceback module's default print would land on STDOUT, inside the verdict), a
    # console code page that cannot hold the payload text quoted in the exception, a pipe
    # nobody reads.
    try:
        sys.stderr.write(text)
        sys.stderr.flush()
    except Exception:
        return


_STDERR_FD = 2


def _divert_fd1():
    """Point fd 1 at stderr (devnull if there is none); the saved fd 1, or None if it could not."""
    try:
        saved = os.dup(1)
    except OSError:
        return None
    # With fd 2 closed, dup() hands back 2 itself, and "stderr" would be stdout again.
    if saved > _STDERR_FD:
        with contextlib.suppress(OSError):
            os.dup2(_STDERR_FD, 1)
            return saved
    sink = os.open(os.devnull, os.O_WRONLY)
    os.dup2(sink, 1)
    os.close(sink)
    return saved


def _flush(streams):
    """Flush each stream that exists; a broken one is no reason to lose the verdict."""
    for stream in streams:
        if stream is not None:
            with contextlib.suppress(Exception):
                stream.flush()


@contextlib.contextmanager
def _stdout_to_stderr():
    # Stdout is the verdict channel. A handler's stray print (or a child process it runs)
    # ahead of the JSON makes the host fail to parse it, and Claude Code and Gemini CLI then
    # treat the hook as a non-blocking error: a deny became an allow, witnessed live.
    sink = sys.stderr if sys.stderr is not None else io.StringIO()
    held = (sys.stdout, sys.__stdout__)
    _flush(held)
    saved = _divert_fd1()
    try:
        with contextlib.redirect_stdout(sink):
            yield
    finally:
        if saved is not None:
            # A stream the handler held on to (sys.__stdout__, a reference cached at import)
            # buffers past redirect_stdout; flushed now it lands on stderr, not after the verdict.
            _flush((sink, *held))
            os.dup2(saved, 1)
            os.close(saved)


def _decide(raw):
    """(stdout_text, exit_code) for one decoded payload: agentseam.dispatch.handle(), inlined."""
    event = parse(raw)
    if event.event == UNKNOWN:
        # A vendor event this adapter has no mapping for. handle() is not called: it
        # reasons about the canonical vocabulary, and handing it something outside that
        # vocabulary invites a decision made on a false premise.
        return "", 0
    try:
        with _stdout_to_stderr():
            result = handle(event)
        decision = _coerce(result)
    except Exception:
        # A door that cannot decide refuses. Escaping here would exit 1 with a traceback,
        # which every host reads as a non-blocking error and allows past; instead the
        # failure is printed for the operator and the gate answers deny in 'openhands''s
        # own dialect. Only the failure's class is named to the host: its message may quote
        # the very payload content the policy was inspecting.
        _report(traceback.format_exc())
        decision = Decision.deny(
            "policy handler failed (%s); refusing rather than allowing what it could not judge"
            % sys.exc_info()[0].__name__
        )
    return respond(degrade(decision, event), event)


def main(stdin=None, stdout=None, exit=True):
    """Read one payload from stdin, dispatch, emit the 'openhands' response, exit."""
    stream = stdin if stdin is not None else sys.stdin
    out = stdout if stdout is not None else sys.stdout
    try:
        raw = json.loads(_read_payload(stream))
    except Exception:
        raw = None
    if not isinstance(raw, dict):
        text, code = _chock_unreadable()
        if text:
            _emit(out, text)
        if exit:
            sys.exit(code)
        return code
    try:
        text, code = _decide(raw)
    except Exception:
        # Past the handler, which _decide() already answers for: a fault in this file on a
        # payload it did decode. With no Event to answer in dialect, the one refusal left is
        # the host's blocking exit code, and nothing on stdout to be misread as a verdict.
        _report(traceback.format_exc())
        text, code = "", 2
    if text:
        _emit(out, text)
    if exit:
        sys.exit(code)
    return code


if __name__ == "__main__":  # pragma: no cover
    main()

